import './Results.css';
function Results(props) {
    function levenshteinDistance(str1, str2) {
        if (str1.length === 0) return str2.length;
        if (str2.length === 0) return str1.length;

        const substitutionCost = str1[0] === str2[0] ? 0 : 1;

        return Math.min(
            levenshteinDistance(str1.substring(1), str2) + 1,
            levenshteinDistance(str1, str2.substring(1)) + 1,
            levenshteinDistance(str1.substring(1), str2.substring(1)) + substitutionCost
        );
    }
    return (
        <>        {props.isCorrect?
        <div className="results">
            <h2 style={{color:'green', textDecoration:'underline'}}>Correct</h2>
            <p>Score: 100% </p>

        </div>
        :
        <div className="results">
        <h2 style = {{color:'red', textDecoration:'underline'}}>Wrong!</h2>
        <p>Score: {1 - levenshteinDistance(props.attempt, props.string) / Math.max(props.attempt, props.string) * 100}%</p></div>
        }
        </>
    )
}
export default Results;
